START TRANSACTION;
SELECT id, invoice_id, amount, currency, status FROM payments WHERE id = 100502 FOR UPDATE;
SELECT id, net_amount, paid_amount, balance_amount FROM student_fee_invoices WHERE id = 5001 FOR UPDATE;
-- Handler has verified the gateway event; stop if payment is already SUCCESS.
-- Execute the allocation branch ONLY if the locked balance >= verified amount.
UPDATE student_fee_invoices SET
 paid_amount = paid_amount + 50000.00,
 balance_amount = balance_amount - 50000.00
WHERE id = 5001 AND balance_amount >= 50000.00;
-- Handler checks exactly one row changed; otherwise roll back local allocation
-- and persist the external confirmation as a reconciliation exception.
UPDATE student_fee_invoices SET status = CASE WHEN balance_amount = 0 THEN 'PAID' ELSE 'PARTIALLY_PAID' END WHERE id = 5001;
UPDATE payments SET gateway_reference = 'GW-002', status = 'SUCCESS', paid_at = '2026-09-28 10:00:00' WHERE id = 100502;
INSERT INTO receipts (id, payment_id, receipt_no, amount, status)
VALUES (502, 100502, 'REC-2026-000502', 50000.00, 'PENDING');
-- Audit and receipt outbox event are inserted before COMMIT.
COMMIT;

