START TRANSACTION;
SELECT * FROM bank_payment_requests WHERE id = 60005 FOR UPDATE;
SELECT id, amount, payment_reference, status FROM salary_batch_items WHERE id = 50005 FOR UPDATE;
-- Apply only a verified matching bank result; an existing SUCCESS is a no-op.
UPDATE bank_payment_requests SET status = 'SUCCESS', external_reference = 'BANK-005' WHERE id = 60005;
UPDATE salary_batch_items SET status = 'SUCCESS', failure_code = NULL WHERE id = 50005;
UPDATE reconciliation_records SET status = 'RESOLVED', resolution = 'Verified BANK-005; no resubmission' WHERE id = 62005;
-- Audit/outbox entry records UNKNOWN -> SUCCESS.
COMMIT;
SELECT status, COUNT(*) AS items, SUM(amount) AS total
FROM salary_batch_items WHERE salary_batch_id = 50 GROUP BY status;
